-- ------------------------------------------
-- 1. Table structure for 'candidates'
-- ------------------------------------------
DROP TABLE IF EXISTS `candidates`;
CREATE TABLE `candidates` (
  `id` VARCHAR(50) NOT NULL PRIMARY KEY,
  `name` VARCHAR(255) DEFAULT NULL,
  `number` VARCHAR(50) DEFAULT NULL,
  `urnName` VARCHAR(255) DEFAULT NULL,
  `whatsapp` VARCHAR(50) DEFAULT NULL,
  `instagram` VARCHAR(255) DEFAULT NULL,
  `facebook` VARCHAR(255) DEFAULT NULL,
  `email` VARCHAR(255) DEFAULT NULL,
  `party` VARCHAR(50) DEFAULT NULL,
  `status` VARCHAR(50) DEFAULT NULL,
  `photoUrl` LONGTEXT DEFAULT NULL,
  `mediaCoordinatorName` VARCHAR(255) DEFAULT NULL,
  `mediaCoordinatorWhatsApp` VARCHAR(50) DEFAULT NULL,
  `professionalBackground` TEXT DEFAULT NULL,
  `areasOfInterest` TEXT DEFAULT NULL,
  `teams` TEXT DEFAULT NULL,
  `family` TEXT DEFAULT NULL,
  `groups` TEXT DEFAULT NULL,
  `trajectory` TEXT DEFAULT NULL,
  `politicalFlags` TEXT DEFAULT NULL,
  `keyContacts` LONGTEXT DEFAULT NULL,
  `publications` LONGTEXT DEFAULT NULL,
  `mappings` LONGTEXT DEFAULT NULL,
  `lastSaved` VARCHAR(100) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------
-- 2. Table structure for 'deadlines'
-- ------------------------------------------
DROP TABLE IF EXISTS `deadlines`;
CREATE TABLE `deadlines` (
  `id` VARCHAR(50) NOT NULL PRIMARY KEY,
  `title` VARCHAR(255) DEFAULT NULL,
  `date` VARCHAR(50) DEFAULT NULL,
  `description` TEXT DEFAULT NULL,
  `daysRemaining` INT DEFAULT NULL,
  `status` VARCHAR(50) DEFAULT NULL,
  `category` VARCHAR(50) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------
-- 3. Table structure for 'reports'
-- ------------------------------------------
DROP TABLE IF EXISTS `reports`;
CREATE TABLE `reports` (
  `id` VARCHAR(50) NOT NULL PRIMARY KEY,
  `title` VARCHAR(255) DEFAULT NULL,
  `createdAt` VARCHAR(100) DEFAULT NULL,
  `content` TEXT DEFAULT NULL,
  `author` VARCHAR(255) DEFAULT NULL,
  `candidateId` VARCHAR(50) DEFAULT NULL,
  `candidateName` VARCHAR(255) DEFAULT NULL,
  `type` VARCHAR(50) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

