ion":"GRANDE FLORIANÓPOLIS","lideranca":"","historicoVotos":"","meta2026":"","situacao":""},{"cityId":"santo-amaro-da-imperatriz","cityName":"Santo Amaro da Imperatriz","region":"GRANDE FLORIANÓPOLIS","lideranca":"","historicoVotos":"","meta2026":"","situacao":""},{"cityId":"balneario-camboriu","cityName":"Balneário Camboriú","region":"VALE DO ITAJAÍ","lideranca":"","historicoVotos":"","meta2026":"","situacao":""},{"cityId":"itajai","cityName":"Itajaí","region":"VALE DO ITAJAÍ","lideranca":"","historicoVotos":"","meta2026":"","situacao":""},{"cityId":"camboriu","cityName":"Camboriú","region":"VALE DO ITAJAÍ","lideranca":"","historicoVotos":"","meta2026":"","situacao":""},{"cityId":"ilhota","cityName":"Ilhota","region":"VALE DO ITAJAÍ","lideranca":"","historicoVotos":"","meta2026":"","situacao":""},{"cityId":"brusque","cityName":"Brusque","region":"VALE DO ITAJAÍ","lideranca":"","historicoVotos":"","meta2026":"","situacao":""},{"cityId":"joinville","cityName":"Joinville","region":"NORTE CATARINENSE","lideranca":"Dr. Luiz (Médico parceiro)","historicoVotos":"4.200","meta2026":"7.000","situacao":"Demanda de ampliação dos leitos de retaguarda pediátricos."},{"cityId":"jaragua-do-sul","cityName":"Jaraguá do Sul","region":"NORTE CATARINENSE","lideranca":"Diretoria Local","historicoVotos":"18.200","meta2026":"25.000","situacao":"Forte base consolidada. Pauta: liberação de recursos para o Hospital São José."},{"cityId":"araquari","cityName":"Araquari","region":"NORTE CATARINENSE","lideranca":"","historicoVotos":"","meta2026":"","situacao":""},{"cityId":"garuva","cityName":"Garuva","region":"NORTE CATARINENSE","lideranca":"","historicoVotos":"","meta2026":"","situacao":""},{"cityId":"sao-francisco-do-sul","cityName":"São Francisco do Sul","region":"NORTE CATARINENSE","lideranca":"","historicoVotos":"","meta2026":"","situacao":""},{"cityId":"ararangua","cityName":"Araranguá","region":"SUL CATARINENSE","lideranca":"","historicoVotos":"","meta2026":"","situacao":""},{"cityId":"