INSERT INTO `reports` (`id`, `title`, `createdAt`, `content`, `author`, `candidateId`, `candidateName`, `type`) VALUES ('rep-1', 'Análise Preliminar de Registro - Dr. Vicente Caropreso', '2026-07-11T20:49:29.543Z', 'O candidato Dr. Vicente Caropreso possui 75% da documentação entregue e validada. Falta apenas o Comprovante de Escolaridade e a Certidão de Filiação Partidária. A situação jurídica está estável, sem impedimentos decorrentes de antecedentes criminais nas justiças federal e estadual.', 'Assessoria Jurídica Federação', 'cand-3', 'Dr. Vicente Caropreso', 'Jurídico');

